=== src/main/java/pousada/service/Reports.java
     1	package pousada.service;
     2	
     3	import pousada.domain.Money;
     4	import pousada.domain.Reservation;
     5	import pousada.domain.Rooms;
     6	
     7	import java.math.BigDecimal;
     8	import java.util.List;
     9	
    10	/** Os relatórios em CSV. Recebem as reservas já filtradas e ordenadas. */
    11	public final class Reports {
    12	    private Reports() {
    13	    }
    14	
    15	    public static BigDecimal kept(Reservation r) {
    16	        return r.amountPaid().subtract(r.refund() == null ? Money.ZERO : r.refund());
    17	    }
    18	
    19	    public static String occupancy(List<Reservation> occupying) {
    20	        StringBuilder csv = new StringBuilder("room,type,reservation,check_in,check_out\n");
    21	        for (Reservation r : occupying) {
    22	            csv.append(r.roomNumber()).append(',')
    23	                    .append(Rooms.find(r.roomNumber()).orElseThrow().type()).append(',')
    24	                    .append(r.id()).append(',')
    25	                    .append(r.checkIn()).append(',')
    26	                    .append(r.checkOut()).append('\n');
    27	        }
    28	        return csv.append("total,").append(occupying.size()).append('/').append(Rooms.count()).append('\n')
    29	                .toString();
    30	    }
    31	
    32	    public static String revenue(List<Reservation> withRevenue) {
    33	        StringBuilder csv = new StringBuilder("reservation,room,check_in,check_out,status,amount\n");
    34	        BigDecimal total = Money.ZERO;
    35	        for (Reservation r : withRevenue) {
    36	            BigDecimal amount = kept(r);
    37	            total = total.add(amount);
    38	            csv.append(r.id()).append(',')
    39	                    .append(r.roomNumber()).append(',')
    40	                    .append(r.checkIn()).append(',')
    41	                    .append(r.checkOut()).append(',')
    42	                    .append(r.status()).append(',')
    43	                    .append(amount.toPlainString()).append('\n');
    44	        }
    45	        return csv.append("total,").append(total.toPlainString()).append('\n').toString();
    46	    }
    47	}
=== src/main/java/pousada/service/ReservationService.java
     1	package pousada.service;
     2	
     3	import pousada.domain.Booking;
     4	import pousada.domain.DomainException;
     5	import pousada.domain.Message;
     6	import pousada.domain.Money;
     7	import pousada.domain.Quote;
     8	import pousada.domain.RatePlan;
     9	import pousada.domain.RatePlans;
    10	import pousada.domain.Receipt;
    11	import pousada.domain.Reservation;
    12	import pousada.domain.ReservationStatus;
    13	import pousada.domain.Room;
    14	import pousada.domain.Rooms;
    15	import pousada.persistence.Database;
    16	import pousada.persistence.MessageRepository;
    17	import pousada.persistence.ReservationRepository;
    18	
    19	import java.sql.Connection;
    20	import java.sql.SQLException;
    21	import java.time.LocalDate;
    22	import java.time.YearMonth;
    23	import java.util.List;
    24	import java.util.function.UnaryOperator;
    25	
    26	public class ReservationService {
    27	    private final Database database;
    28	    private final ReservationRepository reservations = new ReservationRepository();
    29	    private final MessageRepository messages = new MessageRepository();
    30	
    31	    public ReservationService(Database database) {
    32	        this.database = database;
    33	    }
    34	
    35	    public Reservation create(CreateReservation cmd) {
    36	        Room room = Rooms.find(cmd.roomNumber()).orElseThrow(() -> new DomainException(
    37	                404, "ROOM_NOT_FOUND", "Quarto " + cmd.roomNumber() + " não existe."));
    38	        if (cmd.guests() > room.capacity()) {
    39	            throw new DomainException(422, "CAPACITY_EXCEEDED",
    40	                    "O quarto " + room.number() + " comporta até " + room.capacity() + " pessoas.");
    41	        }
    42	        RatePlan plan = RatePlans.find(cmd.ratePlan()).orElseThrow(
    43	                () -> DomainException.invalidRequest("Plano de tarifa desconhecido: " + cmd.ratePlan()));
    44	        Booking booking = new Booking(room, cmd.checkIn(), cmd.checkOut(), cmd.guests(), cmd.companyCode());
    45	        Quote quote = plan.quote(booking);
    46	
    47	        return database.inTransaction(c -> {
    48	            reservations.lockRoom(c, room.number());
    49	            if (reservations.hasOverlap(c, room.number(), cmd.checkIn(), cmd.checkOut())) {
    50	                throw new DomainException(409, "ROOM_UNAVAILABLE",
    51	                        "O quarto " + room.number() + " já está reservado em alguma das noites.");
    52	            }
    53	            return reservations.insert(c, new Reservation(0, room.number(), cmd.guestName(), cmd.guestEmail(),
    54	                    cmd.guestCpf(), cmd.checkIn(), cmd.checkOut(), cmd.guests(), plan.code(), booking.nights(),
    55	                    quote.subtotal(), quote.discount(), quote.total(), ReservationStatus.PENDING,
    56	                    Money.ZERO, null));
    57	        });
    58	    }
    59	
    60	    public Reservation get(long id) {
    61	        return database.inTransaction(c -> load(c, id, false));
    62	    }
    63	
    64	    public Reservation confirm(long id) {
    65	        return database.inTransaction(c -> {
    66	            Reservation confirmed = apply(c, id, Reservation::confirm);
    67	            Receipt receipt = confirmed.receipt(roomOf(confirmed));
    68	            messages.insert(c, Message.confirmationEmail(confirmed, receipt));
    69	            return confirmed;
    70	        });
    71	    }
    72	
    73	    public Reservation cancel(long id) {
    74	        return database.inTransaction(c -> apply(c, id, Reservation::cancel));
    75	    }
    76	
    77	    public Reservation checkIn(long id) {
    78	        return database.inTransaction(c -> apply(c, id, Reservation::startStay));
    79	    }
    80	
    81	    public Receipt checkOut(long id) {
    82	        return database.inTransaction(c -> {
    83	            Reservation done = apply(c, id, Reservation::endStay);
    84	            return done.receipt(roomOf(done));
    85	        });
    86	    }
    87	
    88	    public Receipt document(long id) {
    89	        return database.inTransaction(c -> {
    90	            Reservation r = load(c, id, false);
    91	            return r.receipt(roomOf(r));
    92	        });
    93	    }
    94	
    95	    public List<Message> messages() {
    96	        return database.inTransaction(messages::findAll);
    97	    }
    98	
    99	    public String occupancyReport(LocalDate night) {
   100	        return database.inTransaction(c -> Reports.occupancy(reservations.occupying(c, night)));
   101	    }
   102	
   103	    public String revenueReport(YearMonth month) {
   104	        return database.inTransaction(c -> Reports.revenue(
   105	                reservations.withRevenueStartingBetween(c, month.atDay(1), month.plusMonths(1).atDay(1))));
   106	    }
   107	
   108	    private Reservation apply(Connection c, long id, UnaryOperator<Reservation> transition) throws SQLException {
   109	        Reservation updated = transition.apply(load(c, id, true));
   110	        reservations.update(c, updated);
   111	        return updated;
   112	    }
   113	
   114	    private Reservation load(Connection c, long id, boolean forUpdate) throws SQLException {
   115	        return reservations.findById(c, id, forUpdate).orElseThrow(() -> new DomainException(
   116	                404, "RESERVATION_NOT_FOUND", "Reserva " + id + " não existe."));
   117	    }
   118	
   119	    private static Room roomOf(Reservation r) {
   120	        return Rooms.find(r.roomNumber()).orElseThrow();
   121	    }
   122	}

