     1	package pousada.web;
     2	
     3	import com.fasterxml.jackson.core.JsonProcessingException;
     4	import com.fasterxml.jackson.databind.JsonNode;
     5	import com.fasterxml.jackson.databind.ObjectMapper;
     6	import pousada.domain.DomainException;
     7	import pousada.service.CreateReservation;
     8	
     9	import java.time.LocalDate;
    10	import java.time.YearMonth;
    11	import java.time.format.DateTimeParseException;
    12	
    13	/** Valida o formato do que chega pela API. */
    14	final class RequestParser {
    15	    private RequestParser() {
    16	    }
    17	
    18	    static CreateReservation createReservation(ObjectMapper mapper, String body) {
    19	        JsonNode json;
    20	        try {
    21	            json = mapper.readTree(body);
    22	        } catch (JsonProcessingException e) {
    23	            throw DomainException.invalidRequest("O corpo não é um JSON válido.");
    24	        }
    25	        if (json == null || !json.isObject()) {
    26	            throw DomainException.invalidRequest("O corpo deve ser um objeto JSON.");
    27	        }
    28	        LocalDate checkIn = date(json, "checkIn");
    29	        LocalDate checkOut = date(json, "checkOut");
    30	        if (!checkOut.isAfter(checkIn)) {
    31	            throw DomainException.invalidRequest("A saída deve ser depois da entrada.");
    32	        }
    33	        int guests = integer(json, "guests");
    34	        if (guests < 1) {
    35	            throw DomainException.invalidRequest("É preciso ao menos um hóspede.");
    36	        }
    37	        return new CreateReservation(
    38	                integer(json, "roomNumber"),
    39	                text(json, "guestName"),
    40	                text(json, "guestEmail"),
    41	                text(json, "guestCpf"),
    42	                checkIn,
    43	                checkOut,
    44	                guests,
    45	                text(json, "ratePlan"),
    46	                optionalText(json, "companyCode"));
    47	    }
    48	
    49	    static LocalDate date(String name, String value) {
    50	        try {
    51	            return LocalDate.parse(value);
    52	        } catch (DateTimeParseException | NullPointerException e) {
    53	            throw DomainException.invalidRequest("Parâmetro " + name + " deve estar no formato AAAA-MM-DD.");
    54	        }
    55	    }
    56	
    57	    static YearMonth month(String value) {
    58	        try {
    59	            if (value == null || !value.matches("\\d{4}-\\d{2}")) {
    60	                throw new DateTimeParseException("formato", String.valueOf(value), 0);
    61	            }
    62	            return YearMonth.parse(value);
    63	        } catch (DateTimeParseException e) {
    64	            throw DomainException.invalidRequest("Parâmetro month deve estar no formato AAAA-MM.");
    65	        }
    66	    }
    67	
    68	    private static String text(JsonNode json, String field) {
    69	        JsonNode node = json.get(field);
    70	        if (node == null || !node.isTextual() || node.asText().isBlank()) {
    71	            throw DomainException.invalidRequest("Campo " + field + " é obrigatório.");
    72	        }
    73	        return node.asText();
    74	    }
    75	
    76	    private static String optionalText(JsonNode json, String field) {
    77	        JsonNode node = json.get(field);
    78	        return node != null && node.isTextual() ? node.asText().trim() : null;
    79	    }
    80	
    81	    private static int integer(JsonNode json, String field) {
    82	        JsonNode node = json.get(field);
    83	        if (node == null || !node.isIntegralNumber() || !node.canConvertToInt()) {
    84	            throw DomainException.invalidRequest("Campo " + field + " é obrigatório e deve ser um número inteiro.");
    85	        }
    86	        return node.asInt();
    87	    }
    88	
    89	    private static LocalDate date(JsonNode json, String field) {
    90	        return date(field, text(json, field));
    91	    }
    92	}
