     3	import java.math.BigDecimal;
     4	import java.math.RoundingMode;
     5	import java.text.DecimalFormat;
     6	import java.text.DecimalFormatSymbols;
     7	import java.util.Locale;
     8	
     9	/** Valores em dinheiro: sempre com 2 casas, arredondados meio para o par. */
    10	public final class Money {
    11	    public static final BigDecimal ZERO = of("0");
    12	
    13	    private Money() {
    14	    }
    15	
    16	    public static BigDecimal of(String value) {
    17	        return round(new BigDecimal(value));
    18	    }
    19	
    20	    public static BigDecimal round(BigDecimal value) {
    21	        return value.setScale(2, RoundingMode.HALF_EVEN);
    22	    }
    23	
    24	    /** Percentual (ex.: 12 para 12%) de um valor, arredondado. */
    25	    public static BigDecimal percent(BigDecimal value, int percent) {
    26	        return round(value.multiply(BigDecimal.valueOf(percent)).divide(BigDecimal.valueOf(100)));
    27	    }
    28	
    29	    /** Formato do comprovante: R$ 1.234,56. */
    30	    public static String brl(BigDecimal value) {
    31	        DecimalFormatSymbols symbols = new DecimalFormatSymbols(Locale.ROOT);
