    21	        BigDecimal total,
    22	        ReservationStatus status,
    23	        BigDecimal amountPaid,
    24	        BigDecimal refund) {
    25	
    26	    public Reservation confirm() {
    27	        requireStatus("confirmada", PENDING);
    28	        return with(CONFIRMED, total, refund);
    29	    }
    30	
    31	    public Reservation startStay() {
    32	        requireStatus("receber check-in", CONFIRMED);
    33	        return with(CHECKED_IN, amountPaid, refund);
    34	    }
    35	
    36	    public Reservation endStay() {
    37	        requireStatus("receber check-out", CHECKED_IN);
    38	        return with(CHECKED_OUT, amountPaid, refund);
    39	    }
