    41	    public Reservation cancel() {
    42	        requireStatus("cancelada", PENDING, CONFIRMED);
    43	        return with(CANCELLED, amountPaid, RatePlans.get(ratePlan).refund(amountPaid));
    44	    }
    45	
    46	    public Receipt receipt(Room room) {
    47	        if (!status.isPaid()) {
    48	            throw DomainException.operationNotAllowed("Só reservas pagas têm comprovante.");
    49	        }
    50	        return new Receipt("Comprovante de reserva", id, guestName, guestCpf, roomNumber, room.type(),
    51	                checkIn, checkOut, nights, subtotal, discount, total);
    52	    }
