    54	    private void requireStatus(String action, ReservationStatus... allowed) {
    55	        for (ReservationStatus s : allowed) {
    56	            if (status == s) {
    57	                return;
    58	            }
    59	        }
    60	        throw DomainException.operationNotAllowed(
    61	                "A reserva " + id + " está " + status + " e não pode ser " + action + ".");
    62	    }
    63	
    64	    private Reservation with(ReservationStatus newStatus, BigDecimal newAmountPaid, BigDecimal newRefund) {
    65	        return new Reservation(id, roomNumber, guestName, guestEmail, guestCpf, checkIn, checkOut, guests,
    66	                ratePlan, nights, subtotal, discount, total, newStatus, newAmountPaid, newRefund);
