     1	package pousada.persistence;
     2	
     3	import pousada.domain.Reservation;
     4	import pousada.domain.ReservationStatus;
     5	
     6	import java.sql.Connection;
     7	import java.sql.Date;
     8	import java.sql.PreparedStatement;
     9	import java.sql.ResultSet;
    10	import java.sql.SQLException;
    11	import java.sql.Statement;
    12	import java.time.LocalDate;
    13	import java.util.ArrayList;
    14	import java.util.List;
    15	import java.util.Optional;
    16	
    17	public class ReservationRepository {
    18	
    19	    private static final String PAID = "('CONFIRMED','CHECKED_IN','CHECKED_OUT')";
    20	
    21	    /** Trava as operações de reserva de um mesmo quarto até o fim da transação. */
    22	    public void lockRoom(Connection c, int roomNumber) throws SQLException {
    23	        try (PreparedStatement ps = c.prepareStatement("SELECT pg_advisory_xact_lock(?)")) {
    24	            ps.setLong(1, roomNumber);
    25	            ps.execute();
    26	        }
    27	    }
    28	
    29	    /** Há reserva não cancelada do quarto em alguma noite de [checkIn, checkOut)? */
    30	    public boolean hasOverlap(Connection c, int roomNumber, LocalDate checkIn, LocalDate checkOut)
    31	            throws SQLException {
    32	        String sql = "SELECT 1 FROM reservations WHERE room_number = ? AND status <> 'CANCELLED' "
    33	                + "AND check_in < ? AND check_out > ? LIMIT 1";
    34	        try (PreparedStatement ps = c.prepareStatement(sql)) {
    35	            ps.setInt(1, roomNumber);
    36	            ps.setDate(2, Date.valueOf(checkOut));
    37	            ps.setDate(3, Date.valueOf(checkIn));
    38	            try (ResultSet rs = ps.executeQuery()) {
    39	                return rs.next();
    40	            }
    41	        }
    42	    }
    43	
    44	    public Reservation insert(Connection c, Reservation r) throws SQLException {
    45	        String sql = "INSERT INTO reservations (room_number, guest_name, guest_email, guest_cpf, check_in, "
    46	                + "check_out, guests, rate_plan, nights, subtotal, discount, total, status, amount_paid, refund) "
    47	                + "VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)";
    48	        try (PreparedStatement ps = c.prepareStatement(sql, Statement.RETURN_GENERATED_KEYS)) {
    49	            bind(ps, r);
    50	            ps.executeUpdate();
    51	            try (ResultSet keys = ps.getGeneratedKeys()) {
    52	                keys.next();
    53	                return withId(r, keys.getLong(1));
    54	            }
    55	        }
    56	    }
    57	
    58	    public void update(Connection c, Reservation r) throws SQLException {
    59	        String sql = "UPDATE reservations SET room_number=?, guest_name=?, guest_email=?, guest_cpf=?, "
    60	                + "check_in=?, check_out=?, guests=?, rate_plan=?, nights=?, subtotal=?, discount=?, total=?, "
    61	                + "status=?, amount_paid=?, refund=? WHERE id=?";
    62	        try (PreparedStatement ps = c.prepareStatement(sql)) {
    63	            bind(ps, r);
    64	            ps.setLong(16, r.id());
    65	            ps.executeUpdate();
    66	        }
    67	    }
    68	
    69	    public Optional<Reservation> findById(Connection c, long id, boolean forUpdate) throws SQLException {
    70	        String sql = "SELECT * FROM reservations WHERE id = ?" + (forUpdate ? " FOR UPDATE" : "");
    71	        try (PreparedStatement ps = c.prepareStatement(sql)) {
    72	            ps.setLong(1, id);
    73	            try (ResultSet rs = ps.executeQuery()) {
    74	                return rs.next() ? Optional.of(read(rs)) : Optional.empty();
    75	            }
    76	        }
    77	    }
    78	
    79	    /** Reservas pagas que ocupam um quarto na noite, por número do quarto. */
    80	    public List<Reservation> occupying(Connection c, LocalDate night) throws SQLException {
    81	        return query(c, "SELECT * FROM reservations WHERE status IN " + PAID
    82	                + " AND check_in <= ? AND check_out > ? ORDER BY room_number, id",
    83	                Date.valueOf(night), Date.valueOf(night));
    84	    }
    85	
    86	    /** Reservas que começam no período e deixaram dinheiro com a pousada. */
    87	    public List<Reservation> withRevenueStartingBetween(Connection c, LocalDate from, LocalDate toExclusive)
    88	            throws SQLException {
    89	        return query(c, "SELECT * FROM reservations WHERE check_in >= ? AND check_in < ? "
    90	                + "AND amount_paid - COALESCE(refund, 0) > 0 ORDER BY check_in, id",
    91	                Date.valueOf(from), Date.valueOf(toExclusive));
    92	    }
    93	
    94	    private List<Reservation> query(Connection c, String sql, Date... dates) throws SQLException {
    95	        try (PreparedStatement ps = c.prepareStatement(sql)) {
    96	            for (int i = 0; i < dates.length; i++) {
    97	                ps.setDate(i + 1, dates[i]);
    98	            }
    99	            List<Reservation> result = new ArrayList<>();
   100	            try (ResultSet rs = ps.executeQuery()) {
   101	                while (rs.next()) {
   102	                    result.add(read(rs));
   103	                }
   104	            }
   105	            return result;
   106	        }
   107	    }
   108	
   109	    private static void bind(PreparedStatement ps, Reservation r) throws SQLException {
   110	        ps.setInt(1, r.roomNumber());
   111	        ps.setString(2, r.guestName());
   112	        ps.setString(3, r.guestEmail());
   113	        ps.setString(4, r.guestCpf());
   114	        ps.setDate(5, Date.valueOf(r.checkIn()));
   115	        ps.setDate(6, Date.valueOf(r.checkOut()));
   116	        ps.setInt(7, r.guests());
   117	        ps.setString(8, r.ratePlan());
   118	        ps.setInt(9, r.nights());
   119	        ps.setBigDecimal(10, r.subtotal());
   120	        ps.setBigDecimal(11, r.discount());
   121	        ps.setBigDecimal(12, r.total());
   122	        ps.setString(13, r.status().name());
   123	        ps.setBigDecimal(14, r.amountPaid());
   124	        ps.setBigDecimal(15, r.refund());
   125	    }
   126	
   127	    private static Reservation read(ResultSet rs) throws SQLException {
   128	        return new Reservation(
   129	                rs.getLong("id"),
   130	                rs.getInt("room_number"),
   131	                rs.getString("guest_name"),
   132	                rs.getString("guest_email"),
   133	                rs.getString("guest_cpf"),
   134	                rs.getDate("check_in").toLocalDate(),
   135	                rs.getDate("check_out").toLocalDate(),
   136	                rs.getInt("guests"),
   137	                rs.getString("rate_plan"),
   138	                rs.getInt("nights"),
   139	                rs.getBigDecimal("subtotal"),
   140	                rs.getBigDecimal("discount"),
   141	                rs.getBigDecimal("total"),
   142	                ReservationStatus.valueOf(rs.getString("status")),
   143	                rs.getBigDecimal("amount_paid"),
   144	                rs.getBigDecimal("refund"));
   145	    }
   146	
   147	    private static Reservation withId(Reservation r, long id) {
   148	        return new Reservation(id, r.roomNumber(), r.guestName(), r.guestEmail(), r.guestCpf(), r.checkIn(),
   149	                r.checkOut(), r.guests(), r.ratePlan(), r.nights(), r.subtotal(), r.discount(), r.total(),
   150	                r.status(), r.amountPaid(), r.refund());
   151	    }
   152	}

