    27	                guests      INTEGER       NOT NULL,
    28	                rate_plan   TEXT          NOT NULL,
    29	                nights      INTEGER       NOT NULL,
    30	                subtotal    NUMERIC(12,2) NOT NULL,
    31	                discount    NUMERIC(12,2) NOT NULL,
    32	                total       NUMERIC(12,2) NOT NULL,
    33	                status      TEXT          NOT NULL,
    34	                amount_paid NUMERIC(12,2) NOT NULL,
    35	                refund      NUMERIC(12,2)
    36	            );
    37	            CREATE INDEX IF NOT EXISTS reservations_room_idx ON reservations (room_number, check_in, check_out);
    38	            CREATE TABLE IF NOT EXISTS messages (
    39	                id        BIGSERIAL PRIMARY KEY,
    40	                channel   TEXT NOT NULL,
    41	                recipient TEXT NOT NULL,
    42	                subject   TEXT NOT NULL,
    43	                body      TEXT NOT NULL
    44	            );
    45	            """;
    46	
    47	    private final HikariDataSource dataSource;
    48	
    49	    public Database(String url, String user, String password) {
    50	        HikariConfig config = new HikariConfig();
    51	        config.setJdbcUrl(url);
    52	        config.setUsername(user);
    53	        config.setPassword(password);
    54	        config.setMaximumPoolSize(10);
    55	        config.setInitializationFailTimeout(60_000);
    56	        this.dataSource = new HikariDataSource(config);
    57	    }
    58	
    59	    public void createSchema() {
    60	        inTransaction(connection -> {
    61	            try (Statement statement = connection.createStatement()) {
    62	                // evita corrida entre duas instâncias subindo juntas
    63	                statement.execute("SELECT pg_advisory_xact_lock(-1)");
    64	                statement.execute(SCHEMA);
    65	            }
    66	            return null;
    67	        });
    68	    }
    69	
    70	    public <T> T inTransaction(Work<T> work) {
    71	        try (Connection connection = dataSource.getConnection()) {
    72	            connection.setAutoCommit(false);
    73	            try {
    74	                T result = work.run(connection);
    75	                connection.commit();
    76	                return result;
    77	            } catch (SQLException | RuntimeException e) {
    78	                connection.rollback();
    79	                throw e;
    80	            }
    81	        } catch (SQLException e) {
    82	            throw new IllegalStateException("Erro no banco de dados", e);
    83	        }
    84	    }
    85	
    86	    public void close() {
    87	        dataSource.close();
    88	    }
    89	}
