    22	    public void lockRoom(Connection c, int roomNumber) throws SQLException {
    23	        try (PreparedStatement ps = c.prepareStatement("SELECT pg_advisory_xact_lock(?)")) {
    24	            ps.setLong(1, roomNumber);
