    30	    public boolean hasOverlap(Connection c, int roomNumber, LocalDate checkIn, LocalDate checkOut)
    31	            throws SQLException {
    32	        String sql = "SELECT 1 FROM reservations WHERE room_number = ? AND status <> 'CANCELLED' "
    33	                + "AND check_in < ? AND check_out > ? LIMIT 1";
    34	        try (PreparedStatement ps = c.prepareStatement(sql)) {
    35	            ps.setInt(1, roomNumber);
    36	            ps.setDate(2, Date.valueOf(checkOut));
    37	            ps.setDate(3, Date.valueOf(checkIn));
    38	            try (ResultSet rs = ps.executeQuery()) {
