    44	    public Reservation insert(Connection c, Reservation r) throws SQLException {
    45	        String sql = "INSERT INTO reservations (room_number, guest_name, guest_email, guest_cpf, check_in, "
    46	                + "check_out, guests, rate_plan, nights, subtotal, discount, total, status, amount_paid, refund) "
    47	                + "VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)";
    48	        try (PreparedStatement ps = c.prepareStatement(sql, Statement.RETURN_GENERATED_KEYS)) {
    49	            bind(ps, r);
    50	            ps.executeUpdate();
    51	            try (ResultSet keys = ps.getGeneratedKeys()) {
    52	                keys.next();
    53	                return withId(r, keys.getLong(1));
    54	            }
    55	        }
    56	    }
