    94	    private List<Reservation> query(Connection c, String sql, Date... dates) throws SQLException {
    95	        try (PreparedStatement ps = c.prepareStatement(sql)) {
    96	            for (int i = 0; i < dates.length; i++) {
    97	                ps.setDate(i + 1, dates[i]);
